from collections import Counter

def transform_final_final_format(grid):
    h, w = len(grid), len(grid[0])

    horizontal_features = {}
    for r in range(h):
        row = grid[r]
        nz_vals = [v for v in row if v != 0]
        if len(nz_vals) >= 3:
            counts = Counter(nz_vals)
            most_common = counts.most_common(1)[0]
            ratio = most_common[1] / len(nz_vals)
            if ratio > 0.66:
                horizontal_features[r] = most_common[0]

    horiz_rows = set(horizontal_features.keys())
    vertical_features = {}
    for c in range(w):
        vals = [grid[r][c] for r in range(h) if r not in horiz_rows]
        nz_vals = [v for v in vals if v != 0]
        if len(nz_vals) >= 3:
            counts = Counter(nz_vals)
            most_common = counts.most_common(1)[0]
            ratio = most_common[1] / len(nz_vals)
            if ratio > 0.66:
                vertical_features[c] = most_common[0]

    num_vert = len(vertical_features)
    h_out = 5
    w_out = 2 * num_vert + 1
    output = [[0]*w_out for _ in range(h_out)]

    sorted_vert_cols = sorted(vertical_features.keys())
    h_validity = {}
    for r in horizontal_features.keys():
        row = grid[r]
        valid_count = sum(1 for c in sorted_vert_cols if row[c] == vertical_features[c])
        h_validity[r] = valid_count / num_vert

    sorted_by_validity = sorted(horizontal_features.items(), key=lambda x: (-h_validity[x[0]], x[0]))

    vert_out_map = {sorted_vert_cols[i]: 2 * i + 1 for i in range(num_vert)}
    for c, val in vertical_features.items():
        for r in range(h_out):
            output[r][vert_out_map[c]] = val

    top_n = min(2, len(sorted_by_validity))
    for i in range(top_n):
        r, val = sorted_by_validity[i]
        out_r = 2 * i + 1
        for c in range(w_out):
            if c % 2 == 0:
                output[out_r][c] = val

    return output

